<?php
require_once 'config.php';require_once 'includes/functions.php';wajibLogin();$pageTitle='Stok Barang';
if($_SERVER['REQUEST_METHOD']==='POST'){wajibAdmin();cekCsrf();$id=(int)$_POST['id_barang'];$stok=max(0,(int)$_POST['stok']);$s=$pdo->prepare('UPDATE tokoku_barang SET stok=? WHERE id_barang=?');$s->execute([$stok,$id]);pesan('success','Stok barang berhasil diperbarui.');header('Location: stok.php');exit;}
$rows=$pdo->query('SELECT b.*,k.nama_kategori FROM tokoku_barang b LEFT JOIN tokoku_kategori k ON b.id_kategori=k.id_kategori ORDER BY b.nama_barang')->fetchAll();require 'includes/header.php';?>
<div class="page-intro"><div><span class="eyebrow">INVENTARIS TOKO</span><h2>Stok Barang</h2><p>Pantau jumlah persediaan barang.</p></div></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>Barang</th><th>Kategori</th><th>Harga</th><th>Stok</th><?php if($user['role']==='admin'):?><th>Ubah Stok</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['nama_barang'])?></b></td><td><?=e($r['nama_kategori']??'-')?></td><td><?=rupiah($r['harga'])?></td><td><?=e($r['stok'])?> unit</td><?php if($user['role']==='admin'):?><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id_barang" value="<?=$r['id_barang']?>"><input class="input" style="max-width:100px" type="number" min="0" name="stok" value="<?=$r['stok']?>"><button class="action-btn">Simpan</button></form></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty-state">Belum ada barang. Tambahkan melalui menu Data Barang.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>
